param([Parameter(Mandatory=$true)][string]$ArtifactDir)
$ErrorActionPreference='Stop'
$base='.\optimizer\scripts\r54_2_game_mutation_acceptance_v2.ps1'
$src=Get-Content $base -Raw
$start=$src.IndexOf('$navNew=@''',[StringComparison]::Ordinal)
if($start-lt0){throw 'R54.2 v4 nav block start missing'}
$end=$src.IndexOf("'@.Trim()",$start,[StringComparison]::Ordinal)
if($end-lt0){throw 'R54.2 v4 nav block end missing'}
$end += "'@.Trim()".Length
$b64=''
$replacement=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64))
$src=$src.Substring(0,$start)+$replacement+$src.Substring($end)
$tmp=Join-Path $env:RUNNER_TEMP 'r54_2_game_mutation_acceptance_v4_expanded.ps1'
Set-Content $tmp $src -Encoding UTF8
& $tmp -ArtifactDir $ArtifactDir
if($LASTEXITCODE-ne0){throw "R54.2 GAME mutation v4 failed: $LASTEXITCODE"}
